        assert_eq!(step(parked(0, 2)), Some(2)); // rose -> notify
        assert_eq!(step(SyncStatus::Idle), None); // journal cleared -> reset
        assert_eq!(step(parked(0, 1)), Some(1)); // re-armed -> notify again
    }
}

