        .enabled(is_connected)
        .build(app)
        .map_err(|e| format!("Failed to build logout item: {}", e))?;

    let check_updates_item = MenuItemBuilder::with_id("check_updates", "Check for Updates...")
        .build(app)
        .map_err(|e| format!("Failed to build check updates item: {}", e))?;

